1	package relayproof
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"strings"
9		"sync"
10		"testing"
11	)
12	
13	func openTempQueue(t *testing.T) (*Queue, string) {
14		t.Helper()
15		dir := t.TempDir()
16		q, err := Open(dir)
17		if err != nil {
18			t.Fatalf("Open: %v", err)
19		}
20		return q, dir
21	}
22	
23	func env(id, from, to string, nonce uint64, proofAt, expiresAt int64) Envelope {
24		return Envelope{
25			Message:   Message{ID: id, From: from, To: to, Nonce: nonce, Payload: "p-" + id, ProofAt: proofAt},
26			ExpiresAt: expiresAt,
27		}
28	}
29	
30	func statusOf(t *testing.T, q *Queue, id string) Record {
31		t.Helper()
32		got, ok := q.Query(id)
33		if !ok {
34			t.Fatalf("missing record %s", id)
35		}
36		return Record{
37			Msg:       Envelope{Message: Message{ID: got.ID, From: got.From, To: got.To, Nonce: got.Nonce, Payload: got.Payload, ProofAt: got.ProofAt}, ExpiresAt: got.ExpiresAt},
38			Status:    got.Status,
39			Reason:    got.Reason,
40			NextRetry: got.NextRetry,
41			Attempts:  got.Attempts,
42		}
43	}
44	
45	// End-to-end happy path: waiting until a trusted header covers the proof
46	// height, then delivery with nonce consumption.
47	func TestHappyPath(t *testing.T) {
48		q, _ := openTempQueue(t)
49		defer q.Close()
50	
51		if err := q.RegisterSource("a"); err != nil {
52			t.Fatal(err)
53		}
54		if _, err := q.Submit(env("m1", "a", "b", 1, 100, 0)); err != nil {
55			t.Fatal(err)
56		}
57	
58		// First advance: registered but no header yet -> waiting, retry at +1s.
59		rep, err := q.Advance(1000)
60		if err != nil {
61			t.Fatal(err)
62		}
63		if len(rep.Results) != 1 || rep.Results[0].Status != StatusWaiting {
64			t.Fatalf("want one waiting result, got %+v", rep.Results)
65		}
66		r := statusOf(t, q, "m1")
67		if r.Status != StatusWaiting || r.NextRetry != 2000 || r.Attempts != 1 {
68			t.Fatalf("want waiting retry=2000 attempts=1, got %+v", r)
69		}
70	
71		// Trusted header still short of proof height.
72		if err := q.UpsertHeader(Header{Chain: "a", Height: 99, Trusted: true}); err != nil {
73			t.Fatal(err)
74		}
75		if _, err := q.Advance(2000); err != nil {
76			t.Fatal(err)
77		}
78		r = statusOf(t, q, "m1")
79		if r.Status != StatusWaiting || r.NextRetry != 4000 || r.Attempts != 2 {
80			t.Fatalf("want still waiting retry=4000, got %+v", r)
81		}
82	
83		// Header covering the proof height, but retry time must not be bypassed.
84		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true}); err != nil {
85			t.Fatal(err)
86		}
87		if _, err := q.Advance(3000); err != nil {
88			t.Fatal(err)
89		}
90		r = statusOf(t, q, "m1")
91		if r.Status != StatusWaiting || r.NextRetry != 4000 {
92			t.Fatalf("header must not bypass retry schedule, got %+v", r)
93		}
94	
95		rep, err = q.Advance(4000)
96		if err != nil {
97			t.Fatal(err)
98		}
99		if len(rep.Results) != 1 || rep.Results[0].Status != StatusSuccess {
100			t.Fatalf("want success, got %+v", rep.Results)
101		}
102		r = statusOf(t, q, "m1")
103		if r.Status != StatusSuccess || r.NextRetry != 0 {
104			t.Fatalf("want terminal success without retry, got %+v", r)
105		}
106		if got := q.consumed[newConsumeToken("a", "b", 1)]; got != "m1" {
107			t.Fatalf("nonce not consumed by m1: %q", got)
108		}
109	}
110	
111	// Untrusted headers keep the message waiting; a later trusted one unblocks.
112	func TestUntrustedThenTrustedHeader(t *testing.T) {
113		q, _ := openTempQueue(t)
114		defer q.Close()
115		q.RegisterSource("a")
116		q.Submit(env("m", "a", "b", 1, 10, 0))
117	
118		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: false})
119		q.Advance(1000)
120		if r := statusOf(t, q, "m"); r.Status != StatusWaiting {
121			t.Fatalf("untrusted header: want waiting, got %s", r.Status)
122		}
123		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
124		q.Advance(2000)
125		if r := statusOf(t, q, "m"); r.Status != StatusSuccess {
126			t.Fatalf("trusted header: want success, got %s (%s)", r.Status, r.Reason)
127		}
128	}
129	
130	// Unknown source is permanently rejected on first processing.
131	func TestUnknownSource(t *testing.T) {
132		q, _ := openTempQueue(t)
133		defer q.Close()
134		q.Submit(env("m", "ghost", "b", 1, 10, 0))
135		q.Advance(1000)
136		r := statusOf(t, q, "m")
137		if r.Status != StatusUnknownSrc {
138			t.Fatalf("want unknown-source, got %s (%s)", r.Status, r.Reason)
139		}
140		if !strings.Contains(r.Reason, "ghost") {
141			t.Fatalf("reason should name the chain, got %q", r.Reason)
142		}
143		// Registering the source later must not resurrect a terminal record.
144		if err := q.RegisterSource("ghost"); err != nil {
145			t.Fatal(err)
146		}
147		q.UpsertHeader(Header{Chain: "ghost", Height: 100, Trusted: true})
148		if _, err := q.Advance(2000); err != nil {
149			t.Fatal(err)
150		}
151		if r := statusOf(t, q, "m"); r.Status != StatusUnknownSrc {
152			t.Fatalf("terminal record changed: %s", r.Status)
153		}
154	}
155	
156	// Submission idempotency, conflict, and terminal rejection.
157	func TestSubmitDedupConflictTerminal(t *testing.T) {
158		q, _ := openTempQueue(t)
159		defer q.Close()
160		q.RegisterSource("a")
161	
162		e := env("m1", "a", "b", 1, 10, 0)
163		if _, err := q.Submit(e); err != nil {
164			t.Fatal(err)
165		}
166		before := len(q.order)
167		if _, err := q.Submit(e); err != nil {
168			t.Fatalf("identical resubmit must be idempotent: %v", err)
169		}
170		if len(q.order) != before || len(q.records) != 1 {
171			t.Fatalf("identical resubmit added a queue entry")
172		}
173	
174		diff := e
175		diff.Message.Payload = "changed"
176		if _, err := q.Submit(diff); !errors.Is(err, ErrConflict) {
177			t.Fatalf("want ErrConflict, got %v", err)
178		}
179		if got := statusOf(t, q, "m1"); got.Msg.Message.Payload != "p-m1" {
180			t.Fatalf("original record mutated by conflicting submit")
181		}
182	
183		// Same id, same content after terminalization is still rejected.
184		q.Advance(1000) // unknown? no, source a registered and no header -> waiting
185		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
186		q.Advance(2000) // success
187		if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
188			t.Fatalf("resubmit of terminal id must be ErrTerminal, got %v", err)
189		}
190		if _, err := q.Submit(diff); !errors.Is(err, ErrTerminal) {
191			t.Fatalf("different content on terminal id must be ErrTerminal, got %v", err)
192		}
193	}
194	
195	// Different ids may share a nonce combination, but at most one succeeds; the
196	// loser is recorded as replay when it is processed.
197	func TestReplayAcrossMessages(t *testing.T) {
198		q, _ := openTempQueue(t)
199		defer q.Close()
200		q.RegisterSource("a")
201		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
202	
203		q.Submit(env("win", "a", "b", 9, 10, 0))
204		q.Submit(env("lose", "a", "b", 9, 10, 0))
205		rep, err := q.Advance(1000)
206		if err != nil {
207			t.Fatal(err)
208		}
209		want := map[string]string{"win": StatusSuccess, "lose": StatusReplay}
210		if len(rep.Results) != 2 {
211			t.Fatalf("want 2 results, got %+v", rep.Results)
212		}
213		for _, res := range rep.Results {
214			if res.Status != want[res.ID] {
215				t.Fatalf("id %s want %s got %s", res.ID, want[res.ID], res.Status)
216			}
217		}
218		if r := statusOf(t, q, "lose"); r.Status != StatusReplay ||
219			!strings.Contains(r.Reason, "win") {
220			t.Fatalf("replay reason should name winner, got %+v", r)
221		}
222	}
223	
224	// A waiting message is immediately marked replay once its nonce is consumed
225	// by another message, even while its own retry backoff is still running.
226	func TestReplayWhileWaitingBackoff(t *testing.T) {
227		q, _ := openTempQueue(t)
228		defer q.Close()
229		q.RegisterSource("a")
230	
231		q.Submit(env("early", "a", "b", 5, 10, 0)) // no header yet
232		q.Advance(1000)                            // waiting, retry 2000
233	
234		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
235		q.Submit(env("later", "a", "b", 5, 10, 0))
236		rep, err := q.Advance(1500) // before early's retry of 2000
237		if err != nil {
238			t.Fatal(err)
239		}
240		got := map[string]string{}
241		for _, res := range rep.Results {
242			got[res.ID] = res.Status
243		}
244		if got["later"] != StatusSuccess {
245			t.Fatalf("later should succeed, got %v", got)
246		}
247		if got["early"] != StatusReplay {
248			t.Fatalf("early should be replay despite pending backoff, got %v", got)
249		}
250	}
251	
252	// Absolute expiry: exactly reaching the expiry instant is expired; replay
253	// takes precedence when both conditions hold.
254	func TestExpiryBoundary(t *testing.T) {
255		q, _ := openTempQueue(t)
256		defer q.Close()
257		q.RegisterSource("a")
258		q.Submit(env("m", "a", "b", 1, 10, 5000))
259	
260		q.Advance(4999) // no header -> waiting; not expired
261		if r := statusOf(t, q, "m"); r.Status != StatusWaiting {
262			t.Fatalf("want waiting at 4999, got %s", r.Status)
263		}
264		// Backoff would retry at 5999; at 5000 phase-2 expiry check terminalizes.
265		q.Advance(5000)
266		if r := statusOf(t, q, "m"); r.Status != StatusExpired {
267			t.Fatalf("want expired exactly at 5000, got %s", r.Status)
268		}
269		if r := statusOf(t, q, "m"); r.NextRetry != 0 {
270			t.Fatalf("terminal record must have no retry time")
271		}
272	}
273	
274	func TestReplayBeatsExpiry(t *testing.T) {
275		q, _ := openTempQueue(t)
276		defer q.Close()
277		q.RegisterSource("a")
278		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
279	
280		q.Submit(env("win", "a", "b", 3, 10, 0))
281		q.Submit(env("lose", "a", "b", 3, 10, 5000))
282		q.Advance(5000) // lose is both replay and expired at the same instant
283		if r := statusOf(t, q, "lose"); r.Status != StatusReplay {
284			t.Fatalf("replay must win over expiry, got %s", r.Status)
285		}
286		if r := statusOf(t, q, "win"); r.Status != StatusSuccess {
287			t.Fatalf("win must succeed, got %s", r.Status)
288		}
289	}
290	
291	// A not-yet-expired message with a covering trusted header can still succeed
292	// at its retry instant; one millisecond later it would expire.
293	func TestSuccessJustBeforeExpiry(t *testing.T) {
294		q, _ := openTempQueue(t)
295		defer q.Close()
296		q.RegisterSource("a")
297		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
