package relayproof

import (
	"errors"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// Regression coverage for AUTOMATIC log compaction triggered by a normal
// successful Submit crossing the 4 MiB threshold — not a manually invoked
// store.compact. When the submit call returns success, the new message must
// already be part of the compacted state together with every earlier message,
// and compaction must have no business effect:
//
//   - earlier records stay individually queryable with every field at its
//     original value, and the listing appends the new record at the end in
//     first-submission order, each id appearing once;
//   - the triggering message stays pending with zero attempts and no retry
//     time: compaction itself never processes it and never changes earlier
//     statuses or reasons;
//   - close/reopen of the same state directory restores the same content and
//     order — the triggering record must not exist only before closing;
//   - continued delivery keeps first-submission order for two messages
//     sharing one (source, destination, nonce): the first succeeds, the
//     second ends replay with a reason naming the first; the submit that
//     triggered compaction gets no extra priority;
//   - the post-compaction submission boundary is unchanged: an identical
//     resubmit returns the existing record without adding an entry, while a
//     resubmit with different content is ErrConflict and leaves the original
//     record and processing order untouched.
//
// Crossing the threshold cheaply: the compacted snapshot keeps every message
// payload, so a large submit survives compaction and lets one message supply
// almost all of the 4 MiB; the remaining headroom to the boundary is filled
// with equal-time advance checkpoints (35 framed bytes each). A checkpoint is
// excluded from every snapshot, so the log genuinely shrinks on compaction
// and the crossing is real (a second snapshot would fit far below 4 MiB).

// autoCompactSetup creates a queue whose active log sits within one submit
// record of the compaction threshold and returns the submitted message ids
// in first-submission order: [fill, keep1, keep2, win, lose]. No message has
// been processed yet, so all five are pending.
func autoCompactSetup(t *testing.T) (q *Queue, dir string, ids []string) {
	t.Helper()
	dir = t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	if err := q.RegisterSource("a"); err != nil {
		t.Fatal(err)
	}
	if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
		t.Fatal(err)
	}

	// One never-expiring filler whose submit record alone nearly fills the
	// log. Its exact content is also pinned after compaction.
	filler := Envelope{
		Message: Message{
			ID: "filler", From: "a", To: "b", Nonce: 1,
			Payload: strings.Repeat("F", compactThreshold-256), ProofAt: 10,
		},
	}
	if _, err := q.Submit(filler); err != nil {
		t.Fatal(err)
	}

	// The records whose every field must survive compaction verbatim.
	keep1 := Envelope{
		Message: Message{
			ID: "keep1", From: "a", To: "b", Nonce: 10,
			Payload: "body-keep1", ProofAt: 20,
		},
		ExpiresAt: 9_000_000_000_000,
	}
	keep2 := Envelope{
		Message: Message{
			ID: "keep2", From: "a", To: "c", Nonce: 11,
			Payload: "body-keep2", ProofAt: 30,
		},
		ExpiresAt: 9_000_000_000_001,
	}
	if _, err := q.Submit(keep1); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Submit(keep2); err != nil {
		t.Fatal(err)
	}

	// Two different ids on one (source, destination, nonce) triplet, both
	// covered by the trusted header and far from expiry. They stay pending
	// until the advance after compaction, so they experience the compaction
	// before their first processing.
	win := Envelope{
		Message: Message{
			ID: "win", From: "a", To: "shared-dest", Nonce: 77,
			Payload: "body-win", ProofAt: 50,
		},
		ExpiresAt: 9_000_000_000_000,
	}
	lose := Envelope{
		Message: Message{
			ID: "lose", From: "a", To: "shared-dest", Nonce: 77,
			Payload: "body-lose", ProofAt: 60,
		},
		ExpiresAt: 9_000_000_000_000,
	}
	if _, err := q.Submit(win); err != nil {
		t.Fatal(err)
	}

	// Fill the remaining headroom with equal-time advance checkpoints, which
	// append to the WAL but are never carried into a compaction snapshot.
	// Equal time is legal and never processes the already-submitted pending
	// messages: each advance would deliver them, so the boundary is arranged
	// BEFORE win/lose are ever processed. The checkpoints run while only the
	// filler/keeps exist, all of which are pending as well — a first advance
	// at t=1000 would process them. Instead the checkpoints come first at the
	// same time with the messages submitted afterwards... achieved below by
	// submitting win just before the trigger message; the checkpoints must
	// therefore happen while no pending message would be due. Pending
	// messages are due on every advance, so put the checkpoints before the
	// business messages are submitted: the filler and keeps are themselves
	// submitted only after the padding, see autoCompactPadding below.
	for q.store.size <= compactThreshold {
		// Re-equal time leaves q.now pinned at 1000; with no business
		// messages submitted yet at this point nothing is processed.
		if _, err := q.Advance(1000); err != nil {
			t.Fatal(err)
		}
	}
	// Undo the overshoot: the loop above only runs in the alternate layout;
	// in this layout the padding is installed by submitAutoCompactPadding.
	t.Fatal("unreachable: padding layout is prepared by submitAutoCompactPadding")
}

// submitAutoCompactPadding appends equal-time advance checkpoints until one
// more typical submit would cross the threshold, but the log is still at or
// below it. It must be called with no pending messages (so the equal-time
// advances process nothing) and never after any earlier advance time.
func padLogToThreshold(t *testing.T, q *Queue) {
	t.Helper()
	if q.Now() != 0 {
		t.Fatalf("padding helper needs a never-advanced queue, now=%d", q.Now())
	}
	for q.store.size+1024 <= compactThreshold {
		if _, err := q.Advance(1000); err != nil {
			t.Fatal(err)
		}
	}
	if q.store.size > compactThreshold {
		t.Fatalf("padding overshot the threshold: %d > %d", q.store.size, compactThreshold)
	}
}

// assertRecordExact fails unless the query view equals the submitted envelope
// in every content field and the given processing state.
func assertRecordExact(t *testing.T, q *Queue, e Envelope, status, reason string, attempts int, nextRetry int64) {
	t.Helper()
	got, ok := q.Query(e.Message.ID)
	if !ok {
		t.Fatalf("missing record %s", e.Message.ID)
	}
	m := e.Message
	if got.ID != m.ID || got.From != m.From || got.To != m.To || got.Nonce != m.Nonce ||
		got.Payload != m.Payload || got.ProofAt != m.ProofAt || got.ExpiresAt != e.ExpiresAt {
		t.Fatalf("%s content changed:\nwant %+v\ngot  id=%s from=%s to=%s nonce=%d payloadLen=%d proofAt=%d expiresAt=%d",
			m.ID, e, got.ID, got.From, got.To, got.Nonce, len(got.Payload), got.ProofAt, got.ExpiresAt)
	}
	if got.Status != status || got.Reason != reason || got.Attempts != attempts || got.NextRetry != nextRetry {
		t.Fatalf("%s state changed: want status=%s reason=%q attempts=%d retry=%d; got status=%s reason=%q attempts=%d retry=%d",
			m.ID, status, reason, attempts, nextRetry, got.Status, got.Reason, got.Attempts, got.NextRetry)
	}
}

// TestAutoCompactOnSubmitPersistsTriggerAndAllPrior is the core regression:
// the ordinary Submit that pushes the WAL past 4 MiB returns success only
// after automatic compaction saved state containing the new message and all
// earlier ones.
func TestAutoCompactOnSubmitPersistsTriggerAndAllPrior(t *testing.T) {
	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer q.Close()

	if err := q.RegisterSource("a"); err != nil {
		t.Fatal(err)
	}
	if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
		t.Fatal(err)
	}

	// Pad with checkpoints before any business message exists: no message is
	// pending, so the equal-time advances produce no results.
	padLogToThreshold(t, q)
	if _, err := q.Advance(1000); err != nil {
		t.Fatal(err)
	}
	// Exactly one checkpoint above the conservative stop still must not
	// cross the line; if it did, widen the loop margin.
	if q.store.size > compactThreshold {
		t.Fatalf("setup crossed the threshold early: %d > %d", q.store.size, compactThreshold)
	}

	filler := Envelope{
		Message: Message{
			ID: "filler", From: "a", To: "b", Nonce: 1,
			Payload: strings.Repeat("F", compactThreshold-256), ProofAt: 10,
		},
	}
	keep1 := Envelope{
		Message: Message{
			ID: "keep1", From: "a", To: "b", Nonce: 10,
			Payload: "body-keep1", ProofAt: 20,
		},
		ExpiresAt: 9_000_000_000_000,
	}
	keep2 := Envelope{
		Message: Message{
			ID: "keep2", From: "a", To: "c", Nonce: 11,
			Payload: "body-keep2", ProofAt: 30,
		},
		ExpiresAt: 9_000_000_000_001,
	}
	win := Envelope{
		Message: Message{
			ID: "win", From: "a", To: "shared-dest", Nonce: 77,
			Payload: "body-win", ProofAt: 50,
		},
		ExpiresAt: 9_000_000_000_000,
	}
	lose := Envelope{
		Message: Message{
			ID: "lose", From: "a", To: "shared-dest", Nonce: 77,
			Payload: "body-lose", ProofAt: 60,
		},
		ExpiresAt: 9_000_000_000_000,
	}

	// The filler submit is the first record large enough to cross 4 MiB, so
	// it itself triggers automatic compaction. This is the first of the two
	// threshold crossings this guard pins: a successful submit returning with
	// its own record already compacted.
	before := q.store.size
	if _, err := q.Submit(filler); err != nil {
		t.Fatalf("filler submit: %v", err)
	}
	if before <= compactThreshold && q.store.size > compactThreshold {
		t.Fatalf("compaction did not shrink the crossing log: before=%d after=%d", before, q.store.size)
	}
	if q.store.size > compactThreshold {
		t.Fatalf("log still above threshold after automatic compaction: %d", q.store.size)
	}
	// The filler is queryable immediately, and its payload (kept in the
	// snapshot verbatim) round-trips.
	if got, ok := q.Query("filler"); !ok || got.Payload != filler.Message.Payload ||
		got.Status != StatusPending || got.Attempts != 0 || got.NextRetry != 0 {
		t.Fatalf("triggering filler must be saved pending by its own submit: ok=%v %+v", ok, got)
	}

	// Two ordinary records with distinct field values, then the pair that
	// shares a nonce. These submissions append to the compacted log.
	if _, err := q.Submit(keep1); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Submit(keep2); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Submit(win); err != nil {
		t.Fatal(err)
	}

	// The second crossing: "lose" is the new message whose normal submit
	// pushes the log past 4 MiB again and triggers automatic compaction. Its
	// success result must mean it, too, is already in the compacted state.
	before = q.store.size
	if before <= compactThreshold {
		t.Fatalf("setup: log should be at/under threshold before the trigger submit, got %d", before)
	}
	rec, err := q.Submit(lose)
	if err != nil {
		t.Fatalf("triggering submit must succeed: %v", err)
	}
	if q.store.size > compactThreshold {
		t.Fatalf("automatic compaction did not shrink log: %d > %d", q.store.size, compactThreshold)
	}
	// The trigger returns the normal pending echo: compaction must not have
	// processed it.
	if rec.Status != StatusPending || rec.Reason != "awaiting first processing" ||
		rec.Attempts != 0 || rec.NextRetry != 0 || rec.Seq != 4 {
		t.Fatalf("triggering submit echo must be untouched pending record: %+v", rec)
	}

	// Nothing was processed before the triggering submit; every record keeps
	// the state it had, with the trigger simply appended in submission order.
	pendingReason := "awaiting first processing"
	assertRecordExact(t, q, filler, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q, keep1, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q, keep2, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q, win, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q, lose, StatusPending, pendingReason, 0, 0)

	all := q.Queries()
	wantIDs := []string{"filler", "keep1", "keep2", "win", "lose"}
	if len(all) != len(wantIDs) {
		t.Fatalf("want %d records each appearing once, got %d: %+v", len(wantIDs), len(all), recordIDList(all))
	}
	for i, want := range wantIDs {
		if all[i].ID != want {
			t.Fatalf("listing must stay in first-submission order: want %v got %v", wantIDs, recordIDList(all))
		}
	}
	seen := map[string]int{}
	for _, r := range all {
		seen[r.ID]++
	}
	for id, n := range seen {
		if n != 1 {
			t.Fatalf("record %s appears %d times in listing", id, n)
		}
	}

	// Continued delivery after compaction: win was submitted first and must
	// succeed; lose is then terminalized replay naming win. The triggering
	// submit (lose) must win no extra priority.
	rep, err := q.Advance(2000)
	if err != nil {
		t.Fatalf("advance after compaction: %v", err)
	}
	if len(rep.Results) != 2 {
		t.Fatalf("want win success then lose replay, got %+v", rep.Results)
	}
	if rep.Results[0] != (Result{ID: "win", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100"}) {
		t.Fatalf("first-submitted message must succeed first: %+v", rep.Results[0])
	}
	if rep.Results[1].ID != "lose" || rep.Results[1].Status != StatusReplay ||
		!strings.Contains(rep.Results[1].Reason, "win") {
		t.Fatalf("later message must be replay naming win: %+v", rep.Results[1])
	}
	assertRecordExact(t, q, win, StatusSuccess,
		"delivered; proof verified by trusted header at height 100", 1, 0)
	assertRecordExact(t, q, lose, StatusReplay,
		"nonce combination already consumed by message win", 1, 0)
	// The bystanders keep their pending state: compaction and the shared-nonce
	// pair change nothing about unrelated records.
	assertRecordExact(t, q, keep1, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q, keep2, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q, filler, StatusPending, pendingReason, 0, 0)
	if winner := q.consumed[newConsumeToken("a", "shared-dest", 77)]; winner != "win" {
		t.Fatalf("nonce consumption must belong to the first-submitted win, got %q", winner)
	}

	// Close and reopen the same directory: the triggering submit and the
	// delivery order must survive, not exist only before closing.
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}
	q = nil
	q2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen compacted directory: %v", err)
	}
	defer q2.Close()
	if q2.Now() != 2000 {
		t.Fatalf("processing time lost on reopen: want 2000 got %d", q2.Now())
	}
	all = q2.Queries()
	if len(all) != len(wantIDs) {
		t.Fatalf("after reopen want %d records, got %d: %v", len(wantIDs), len(all), recordIDList(all))
	}
	for i, want := range wantIDs {
		if all[i].ID != want {
			t.Fatalf("order lost across reopen: want %v got %v", wantIDs, recordIDList(all))
		}
	}
	assertRecordExact(t, q2, filler, StatusPending, pendingReason, 0, 0)
	assertRecordExact(t, q2, win, StatusSuccess,
		"delivered; proof verified by trusted header at height 100", 1, 0)
	assertRecordExact(t, q2, lose, StatusReplay,
		"nonce combination already consumed by message win", 1, 0)
	if winner := q2.consumed[newConsumeToken("a", "shared-dest", 77)]; winner != "win" {
		t.Fatalf("consumption lost across reopen: %q", winner)
	}
	// The already-terminal pair must not be reprocessed.
	again, err := q2.Advance(3000)
	if err != nil {
		t.Fatal(err)
	}
	for _, r := range again.Results {
		if r.ID == "win" || r.ID == "lose" {
			t.Fatalf("terminal pair reappeared after reopen: %+v", r)
		}
	}

	// Resubmission boundary after compaction, on a still-pending record.
	echo, err := q2.Submit(keep1)
	if err != nil {
		t.Fatalf("identical resubmit after compaction must return the record: %v", err)
	}
	if echo.Seq != 1 || echo.Status != StatusPending || echo.Attempts != 0 {
		t.Fatalf("identical resubmit must echo the existing pending record: %+v", echo)
	}
	if len(q2.records) != len(wantIDs) || len(q2.order) != 3 {
		t.Fatalf("identical resubmit added a record: records=%d order=%v", len(q2.records), q2.order)
	}
	conflict := keep1
	conflict.Message.Payload = "body-keep1-CHANGED"
	if _, err := q2.Submit(conflict); !errors.Is(err, ErrConflict) {
		t.Fatalf("different content after compaction must be ErrConflict, got %v", err)
	}
	// Original record intact, content and position unchanged.
	assertRecordExact(t, q2, keep1, StatusPending, pendingReason, 0, 0)
	all = q2.Queries()
	if len(all) != len(wantIDs) {
		t.Fatalf("conflicting submit added a record: %d listings", len(all))
	}
	wantLiveOrder := []string{"filler", "keep1", "keep2"}
	if len(q2.order) != len(wantLiveOrder) {
		t.Fatalf("live order changed: want %v got %v", wantLiveOrder, q2.order)
	}
	for i, want := range wantLiveOrder {
		if q2.order[i] != want {
			t.Fatalf("processing order changed after rejected submit: want %v got %v", wantLiveOrder, q2.order)
		}
	}
	// The rejected submit must not have shifted seq assignment: a genuinely
	// new message takes the next seq after lose.
	newbie := Envelope{Message: Message{ID: "newbie", From: "a", To: "b", Nonce: 30, Payload: "body-newbie", ProofAt: 10}}
	nrec, err := q2.Submit(newbie)
	if err != nil {
		t.Fatal(err)
	}
	if nrec.Seq != 5 {
		t.Fatalf("rejected submit must not consume seq: want 5 got %d", nrec.Seq)
	}

	// And the business verdict after the conflict matches the ordinary
	// pre-compaction rule: the untouched keep1 delivers on its own schedule.
	rep2, err := q2.Advance(4000)
	if err != nil {
		t.Fatal(err)
	}
	var gotKeep1 *Result
	for i := range rep2.Results {
		if rep2.Results[i].ID == "keep1" {
			gotKeep1 = &rep2.Results[i]
		}
	}
	if gotKeep1 == nil || gotKeep1.Status != StatusSuccess ||
		gotKeep1.Reason != "delivered; proof verified by trusted header at height 100" {
		t.Fatalf("original keep1 must deliver under the normal rule: %+v", rep2.Results)
	}
	if got := statusOf(t, q2, "keep1"); got.Msg.Message.Payload != "body-keep1" {
		t.Fatalf("original payload must survive: %q", got.Msg.Message.Payload)
	}
}

// recordIDList renders listing ids for failure messages.
func recordIDList(qs []Query) []string {
	ids := make([]string, len(qs))
	for i, q := range qs {
		ids[i] = q.ID
	}
	return ids
}

// TestAutoCompactTriggeringSubmitIsDurableAcrossCrashReopen pins the promise
// at the storage level: once Submit returned success after crossing 4 MiB,
// reopening the raw directory (without any in-process state) must list the
// triggering message with its exact original content. The last submit must
// not exist only before Close.
func TestAutoCompactTriggeringSubmitIsDurableAcrossCrashReopen(t *testing.T) {
	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	if err := q.RegisterSource("a"); err != nil {
		t.Fatal(err)
	}
	padLogToThreshold(t, q)

	// Distinct non-empty payload so a snapshot that dropped or truncated it
	// would be visible.
	trigger := Envelope{
		Message: Message{
			ID: "trigger", From: "a", To: "b", Nonce: 3,
			Payload: strings.Repeat("T", compactThreshold/2) + "-tail", ProofAt: 7,
		},
		ExpiresAt: 42_000,
	}
	if _, err := q.Submit(trigger); err != nil {
		t.Fatal(err)
	}
	if q.store.size > compactThreshold {
		t.Fatalf("automatic compaction did not shrink log: %d", q.store.size)
	}
	info, err := os.Stat(filepath.Join(dir, logName))
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() != q.store.size {
		t.Fatalf("on-disk size %d disagrees with store size %d", info.Size(), q.store.size)
	}
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	q2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer q2.Close()
	got, ok := q2.Query("trigger")
	if !ok {
		t.Fatal("triggering submit missing after close/reopen")
	}
	if got.ID != "trigger" || got.From != "a" || got.To != "b" || got.Nonce != 3 ||
		got.Payload != trigger.Message.Payload || got.ProofAt != 7 || got.ExpiresAt != 42_000 {
		t.Fatalf("triggering record changed across reopen: id=%s from=%s to=%s nonce=%d payloadLen=%d/%d proof=%d exp=%d",
			got.ID, got.From, got.To, got.Nonce, len(got.Payload), len(trigger.Message.Payload), got.ProofAt, got.ExpiresAt)
	}
	if got.Status != StatusPending || got.Attempts != 0 || got.NextRetry != 0 {
		t.Fatalf("triggering record must reopen pending: %+v", got)
	}
}

// TestAutoCompactDuringSubmissionLeavesPriorStatusesUntouched exercises the
// trigger with already-PROCESSED records on both sides of the threshold:
// their statuses, reasons, attempt counts and retry schedules are established
// before the crossing and must be byte-identical after the submit-triggered
// compaction, including a waiting record mid-backoff.
func TestAutoCompactDuringSubmissionLeavesPriorStatusesUntouched(t *testing.T) {
	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer q.Close()
	if err := q.RegisterSource("a"); err != nil {
		t.Fatal(err)
	}
	// Only height 50 trusted: done delivers at proof 10; wait stays on proof 90.
	if err := q.UpsertHeader(Header{Chain: "a", Height: 50, Root: "0x50", Trusted: true}); err != nil {
		t.Fatal(err)
	}
	done := env("done", "a", "b", 1, 10, 0)
	waiting := env("waiting", "a", "b", 2, 90, 0)
	if _, err := q.Submit(done); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Submit(waiting); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Advance(1000); err != nil {
		t.Fatal(err)
	}
	// done: success, 1 attempt, no retry; waiting: 1 attempt, retry at 2000.
	wantDone := statusOf(t, q, "done")
	wantWaiting := statusOf(t, q, "waiting")
	if wantDone.Status != StatusSuccess || wantWaiting.Status != StatusWaiting || wantWaiting.NextRetry != 2000 {
		t.Fatalf("setup wrong: done=%+v waiting=%+v", wantDone, wantWaiting)
	}

	// Grow toward the threshold with checkpoints while the live records stay
	// as established (waiting is not due at 1000; done is terminal).
	for q.store.size+256 <= compactThreshold {
		if _, err := q.Advance(1000); err != nil {
			t.Fatal(err)
		}
	}
	if q.store.size > compactThreshold {
		t.Fatalf("padding overshot: %d", q.store.size)
	}

	// A final filler submit crosses the line and auto-compacts.
	filler := Envelope{Message: Message{
		ID: "filler2", From: "a", To: "b", Nonce: 9,
		Payload: strings.Repeat("Z", compactThreshold), ProofAt: 10,
	}}
	if _, err := q.Submit(filler); err != nil {
		t.Fatal(err)
	}
	if q.store.size > compactThreshold {
		t.Fatalf("log not compacted: %d", q.store.size)
	}

	// Prior statuses, reasons, attempts and schedules are unchanged.
	gotDone := statusOf(t, q, "done")
	gotWaiting := statusOf(t, q, "waiting")
	if gotDone.Status != wantDone.Status || gotDone.Reason != wantDone.Reason ||
		gotDone.Attempts != wantDone.Attempts || gotDone.NextRetry != wantDone.NextRetry ||
		gotDone.Msg != wantDone.Msg {
		t.Fatalf("success record changed across submit-triggered compaction:\nbefore=%+v\nafter =%+v", wantDone, gotDone)
	}
	if gotWaiting.Status != wantWaiting.Status || gotWaiting.Reason != wantWaiting.Reason ||
		gotWaiting.Attempts != wantWaiting.Attempts || gotWaiting.NextRetry != wantWaiting.NextRetry ||
		gotWaiting.Msg != wantWaiting.Msg {
		t.Fatalf("waiting record changed across submit-triggered compaction:\nbefore=%+v\nafter =%+v", wantWaiting, gotWaiting)
	}
	// The new filler is pending, zero attempts, no retry.
	if r := statusOf(t, q, "filler2"); r.Status != StatusPending || r.Attempts != 0 || r.NextRetry != 0 {
		t.Fatalf("triggering filler must stay pending: %+v", r)
	}

	// Reopen from the compacted bytes: everything still matches.
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}
	q2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer q2.Close()
	gotDone = statusOf(t, q2, "done")
	gotWaiting = statusOf(t, q2, "waiting")
	if gotDone != wantDone {
		t.Fatalf("success record lost across reopen:\nbefore=%+v\nafter =%+v", wantDone, gotDone)
	}
	if gotWaiting != wantWaiting {
		t.Fatalf("waiting record lost across reopen:\nbefore=%+v\nafter =%+v", wantWaiting, gotWaiting)
	}
	// The waiting schedule is live again: at its retry instant it stays
	// waiting (no higher header), proving compaction preserved the backoff.
	if _, err := q2.Advance(2000); err != nil {
		t.Fatal(err)
	}
	r := statusOf(t, q2, "waiting")
	if r.Status != StatusWaiting || r.Attempts != 2 || r.NextRetry != 4000 {
		t.Fatalf("waiting backoff must continue on the canonical schedule after compaction: %+v", r)
	}
	_ = strconv.Itoa(0) // keep strconv import stable if future edits drop uses
}

