package relayproof

import (
	"fmt"
	"strings"
	"testing"
)

func TestDbgReal(t *testing.T) {
	const margin = int64(4096)
	fillerTmpl := Envelope{Message: Message{ID: "filler", From: "a", To: "b", Nonce: 99, ProofAt: 10}}
	keep1 := Envelope{Message: Message{ID: "keep1", From: "a", To: "b", Nonce: 10, Payload: "body-keep1", ProofAt: 20}, ExpiresAt: 9e12}
	keep2 := Envelope{Message: Message{ID: "keep2", From: "a", To: "c", Nonce: 11, Payload: "body-keep2", ProofAt: 30}, ExpiresAt: 9e12 + 1}
	win := Envelope{Message: Message{ID: "win", From: "a", To: "shared-dest", Nonce: 77, Payload: "body-win", ProofAt: 50}, ExpiresAt: 9e12}
	lose := Envelope{Message: Message{ID: "lose", From: "a", To: "shared-dest", Nonce: 77, Payload: "body-lose", ProofAt: 60}, ExpiresAt: 9e12}

	gaugeBase, cp, smallFrames := gaugeFrames(t, []Envelope{keep1, keep2, win, lose})
	var smallTotal int64
	for _, f := range smallFrames { fmt.Printf("gauge small frame=%d\n", f); smallTotal += f }
	fillerOverhead := submitOverhead(t, fillerTmpl, 4096)
	fmt.Printf("gaugeBase=%d cp=%d smallTotal=%d overhead=%d\n", gaugeBase, cp, smallTotal, fillerOverhead)
	L := compactThreshold - margin - gaugeBase - cp - smallTotal - fillerOverhead
	fillerFrame := fillerOverhead + L
	n := int((margin+cp)/cp) + 1
	fmt.Printf("L=%d fillerFrame=%d n=%d pad=%d\n", L, fillerFrame, n, int64(n)*cp)

	q, _ := openTempQueue(t)
	defer q.Close()
	q.RegisterSource("a")
	q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true})
	base := q.store.size
	for i := 0; i < n; i++ { q.Advance(1000) }
	fmt.Printf("real base=%d afterPad=%d\n", base, q.store.size)
	for _, e := range []Envelope{
		{Message: Message{ID: "filler", From: "a", To: "b", Nonce: 99, Payload: strings.Repeat("Z", int(L)), ProofAt: 10}},
		keep1, keep2, win,
	} {
		b := q.store.size
		q.Submit(e)
		fmt.Printf("submit %-6s frame=%d size=%d\n", e.Message.ID, q.store.size-b, q.store.size)
	}
	preLose := q.store.size
	q.Submit(lose)
	fmt.Printf("LOSE crossing pre=%d post=%d predicted=%d delta=%d\n",
		preLose, q.store.size, base+cp+fillerFrame+smallTotal, q.store.size-(base+cp+fillerFrame+smallTotal))
}
EOF
go test ./relayproof/ -run TestDbgReal -v 2>&1 | grep -vE '=== RUN|--- PASS|PASS|ok|^$' ; rm relayproof/zz_dbg_test.go

